<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Job Application</h1>

    @* Step Indicator Bar *@
    <nav class="mb-4">
        <ol class="d-flex list-unstyled justify-content-between position-relative step-indicator">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < _currentStep;
                var isCurrent = stepIndex == _currentStep;
                var isFuture = stepIndex > _currentStep;

                <li class="text-center flex-fill">
                    <button type="button"
                            class="btn btn-link text-decoration-none p-0 @(isFuture ? "disabled" : "")"
                            disabled="@(isFuture || _submitted)"
                            @onclick="() => GoToStep(stepIndex)">
                        <span class="d-inline-flex align-items-center justify-content-center rounded-circle border @(isCurrent ? "bg-primary text-white border-primary" : isCompleted ? "bg-success text-white border-success" : "bg-light text-muted border-secondary")"
                              style="width: 36px; height: 36px; font-size: 0.85rem;">
                            @if (isCompleted)
                            {
                                <span>&#10003;</span>
                            }
                            else
                            {
                                <span>@(stepIndex + 1)</span>
                            }
                        </span>
                        <div class="small mt-1 @(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                            @_stepNames[stepIndex]
                        </div>
                    </button>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @if (_submitted)
    {
        @* Confirmation *@
        <div class="alert alert-success text-center py-5">
            <h2 class="mb-3">&#10003; Application Submitted!</h2>
            <p class="lead">Your application has been received.</p>
            <p class="fs-4">Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        @* Step 1: Personal Info *@
        @if (_currentStep == 0)
        {
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Personal Information</h4></div>
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="_fullName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="_email" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="_phone" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Address <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="_address" />
                    </div>
                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                            @if (_isValidating)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Next
                        </button>
                    </div>
                </div>
            </div>
        }

        @* Step 2: Work History *@
        @if (_currentStep == 1)
