                                        @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                            <div class="row">
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="_workEntries[index].Company" />
                                </div>
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="_workEntries[index].Title" />
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-4 mb-3">
                                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                    <input type="date" class="form-control" @bind="_workEntries[index].StartDate" />
                                </div>
                                <div class="col-md-4 mb-3">
