                                <small>@r.Email &bull; @r.Phone</small>
                            </div>
                        }
                    </div>
                    <hr />

                    @* Cover Letter Summary *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h5>Cover Letter</h5>
                            <button class="btn btn-sm btn-link" @onclick="() => GoToStep(3)">Edit</button>
                        </div>
                        <p class="mb-0" style="white-space: pre-wrap;">@_coverLetter</p>
                    </div>
                    <hr />

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                            @if (_isSubmitting)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Submit Application
