                            class="btn btn-link text-decoration-none p-0 @(isFuture ? "disabled" : "")"
                            disabled="@(isFuture || _submitted)"
                            @onclick="() => GoToStep(stepIndex)">
                        <span class="d-inline-flex align-items-center justify-content-center rounded-circle border @(isCurrent ? "bg-primary text-white border-primary" : isCompleted ? "bg-success text-white border-success" : "bg-light text-muted border-secondary")"
                              style="width: 36px; height: 36px; font-size: 0.85rem;">
                            @if (isCompleted)
                            {
                                <span>&#10003;</span>
                            }
                            else
                            {
                                <span>@(stepIndex + 1)</span>
                            }
                        </span>
                        <div class="small mt-1 @(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                            @_stepNames[stepIndex]
                        </div>
                    </button>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @if (_submitted)
    {
        @* Confirmation *@
        <div class="alert alert-success text-center py-5">
            <h2 class="mb-3">&#10003; Application Submitted!</h2>
            <p class="lead">Your application has been received.</p>
            <p class="fs-4">Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        @* Step 1: Personal Info *@
        @if (_currentStep == 0)
        {
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Personal Information</h4></div>
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="_fullName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="_email" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="_phone" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Address <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="_address" />
                    </div>
                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                            @if (_isValidating)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Next
                        </button>
                    </div>
                </div>
            </div>
        }

        @* Step 2: Work History *@
        @if (_currentStep == 1)
        {
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Work History</h4></div>
                <div class="card-body">
                    @for (int i = 0; i < _workEntries.Count; i++)
                    {
                        var index = i;
                        <div class="border rounded p-3 mb-3 position-relative">
                            <h6>Position @(index + 1)</h6>
                            @if (_workEntries.Count > 1)
                            {
                                <button type="button" class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
                                        @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                            <div class="row">
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="_workEntries[index].Company" />
                                </div>
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="_workEntries[index].Title" />
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-4 mb-3">
                                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                    <input type="date" class="form-control" @bind="_workEntries[index].StartDate" />
                                </div>
                                <div class="col-md-4 mb-3">
                                    <label class="form-label">End Date</label>
                                    <input type="date" class="form-control" @bind="_workEntries[index].EndDate"
                                           disabled="@_workEntries[index].IsCurrent" />
                                </div>
                                <div class="col-md-4 mb-3 d-flex align-items-end">
                                    <div class="form-check">
                                        <input type="checkbox" class="form-check-input" id="@($"current-{index}")"
                                               @bind="_workEntries[index].IsCurrent" />
                                        <label class="form-check-label" for="@($"current-{index}")">Currently working here</label>
                                    </div>
                                </div>
                            </div>
                            <div class="mb-3">
                                <label class="form-label">Description</label>
                                <textarea class="form-control" rows="3" @bind="_workEntries[index].Description"></textarea>
                            </div>
                        </div>
                    }

                    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
                        + Add Another Position
                    </button>

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
                    </div>
                </div>
            </div>
        }

        @* Step 3: References *@
        @if (_currentStep == 2)
        {
            <div class="card">
                <div class="card-header"><h4 class="mb-0">References</h4></div>
                <div class="card-body">
                    @for (int i = 0; i < _references.Count; i++)
                    {
                        var index = i;
                        <div class="border rounded p-3 mb-3 position-relative">
                            <h6>Reference @(index + 1)</h6>
                            @if (_references.Count > 2)
                            {
                                <button type="button" class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
                                        @onclick="() => RemoveReference(index)">Remove</button>
                            }
                            <div class="row">
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Name <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="_references[index].Name" />
                                </div>
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="_references[index].Relationship" />
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Email <span class="text-danger">*</span></label>
                                    <input type="email" class="form-control" @bind="_references[index].Email" />
                                </div>
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                                    <input type="tel" class="form-control" @bind="_references[index].Phone" />
                                </div>
                            </div>
                        </div>
                    }

                    @if (_references.Count < 3)
                    {
                        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                            + Add Reference
                        </button>
                    }

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
                    </div>
                </div>
            </div>
        }

        @* Step 4: Cover Letter *@
        @if (_currentStep == 3)
        {
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Cover Letter</h4></div>
                <div class="card-body">
                    <div class="mb-3">
                        <textarea class="form-control" rows="12" maxlength="2000"
                                  @bind="_coverLetter" @bind:event="oninput"></textarea>
                        <div class="form-text text-end">
                            @(_coverLetter?.Length ?? 0) / 2000 characters
                        </div>
                    </div>
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-primary" @onclick="NextStep">Next</button>
                    </div>
                </div>
            </div>
        }

        @* Step 5: Review & Submit *@
        @if (_currentStep == 4)
        {
            <div class="card">
                <div class="card-header"><h4 class="mb-0">Review & Submit</h4></div>
                <div class="card-body">

                    @* Personal Info Summary *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h5>Personal Information</h5>
                            <button class="btn btn-sm btn-link" @onclick="() => GoToStep(0)">Edit</button>
                        </div>
                        <dl class="row mb-0">
                            <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                            <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                            <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                            <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                        </dl>
                    </div>
                    <hr />

                    @* Work History Summary *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h5>Work History</h5>
                            <button class="btn btn-sm btn-link" @onclick="() => GoToStep(1)">Edit</button>
                        </div>
                        @foreach (var entry in _workEntries)
                        {
                            <div class="mb-2 ps-3 border-start">
                                <strong>@entry.Title</strong> at @entry.Company<br />
                                <small class="text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                                </small>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p class="mb-0 mt-1">@entry.Description</p>
                                }
                            </div>
                        }
                    </div>
                    <hr />

                    @* References Summary *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h5>References</h5>
                            <button class="btn btn-sm btn-link" @onclick="() => GoToStep(2)">Edit</button>
                        </div>
                        @foreach (var r in _references)
                        {
                            <div class="mb-2 ps-3 border-start">
                                <strong>@r.Name</strong> (@r.Relationship)<br />
                                <small>@r.Email &bull; @r.Phone</small>
                            </div>
                        }
                    </div>
                    <hr />

                    @* Cover Letter Summary *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center">
                            <h5>Cover Letter</h5>
                            <button class="btn btn-sm btn-link" @onclick="() => GoToStep(3)">Edit</button>
                        </div>
                        <p class="mb-0" style="white-space: pre-wrap;">@_coverLetter</p>
                    </div>
                    <hr />

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                        <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                            @if (_isSubmitting)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Submit Application
                        </button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep;
    private string? _errorMessage;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
            _errorMessage = null;
        }
    }

    private void NextStep()
    {
        _errorMessage = null;
        _currentStep++;
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        _currentStep--;
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!isValid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
            _currentStep++;
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = null;
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                _errorMessage = "Please fill in company, title, and start date for all positions.";
                return;
            }
        }
        _currentStep++;
    }

    private void NextFromReferences()
    {
        _errorMessage = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        _currentStep++;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = null;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(
                _workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate,
                    e.IsCurrent ? null : e.EndDate,
                    e.Description ?? ""
                )).ToList()
            );
            var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, references, _coverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
